/** Stops each engine only once its sockets have closed, so no close is logged after a suite restores its logger. */
export async function stopWhenIdle(engines: HalServer[]): Promise<void> {
  clients.splice(0).forEach(client => client.terminate());
  await Promise.all(
    engines.splice(0).map(async hal => {
      await settled(() => hal.wss.clients.size === 0);
      await hal.stop();
    })
  );
}

